    auto paint_dispatch_debug_stage_name(
        PaintDispatchDebugStage stage) -> const char*
    {
        switch (stage)
        {
        case PaintDispatchDebugStage::Idle:
            return "idle";
        case PaintDispatchDebugStage::DrainQueue:
            return "drain_queue";
        case PaintDispatchDebugStage::ParseRequest:
            return "parse_request";
        case PaintDispatchDebugStage::ResolveContext:
            return "resolve_context";
        case PaintDispatchDebugStage::InspectPaintMaterial:
            return "inspect_paint_material";
        case PaintDispatchDebugStage::DiscoverMesh:
            return "discover_mesh";
        case PaintDispatchDebugStage::LoadProfile:
            return "load_profile";
        case PaintDispatchDebugStage::ResolvePose:
            return "resolve_pose";
        case PaintDispatchDebugStage::BuildPlanner:
            return "build_planner";
        case PaintDispatchDebugStage::ResolveComponentTransform:
            return "resolve_component_transform";
        case PaintDispatchDebugStage::SkinProfile:
            return "skin_profile";
        case PaintDispatchDebugStage::ResolveRuntimeTriangles:
            return "resolve_runtime_triangles";
        case PaintDispatchDebugStage::WarmRuntimeTriangles:
            return "warm_runtime_triangles";
        case PaintDispatchDebugStage::ResolveViewport:
            return "resolve_viewport";
        case PaintDispatchDebugStage::ProjectRuntimeTriangles:
            return "project_runtime_triangles";
        case PaintDispatchDebugStage::CaptureBaseColor:
            return "capture_base_color";
        case PaintDispatchDebugStage::CaptureAppearanceSource:
            return "capture_appearance_source";
        case PaintDispatchDebugStage::PrepareAppearance:
            return "prepare_appearance";
        case PaintDispatchDebugStage::QueryAppearanceSource:
            return "query_appearance_source";
        case PaintDispatchDebugStage::FitAppearance:
            return "fit_appearance";
        case PaintDispatchDebugStage::BuildStrokePlan:
            return "build_stroke_plan";
        case PaintDispatchDebugStage::ImportPreview:
            return "import_preview";
        case PaintDispatchDebugStage::TickDirectPaint:
            return "tick_direct_paint";
        }
        return "unknown";
    }

    void paint_dispatch_set_debug_stage(PaintDispatchDebugStage stage)
    {
        g_paint_dispatch_debug_stage.store(
            static_cast<int>(stage),
            std::memory_order_release);
    }

    void paint_dispatch_reset_exception_diagnostics()
    {
        g_paint_dispatch_exception_code.store(
            ERROR_SUCCESS,
            std::memory_order_release);
        g_paint_dispatch_exception_address.store(
            0,
            std::memory_order_release);
        g_paint_dispatch_exception_parameter_count.store(
            0,
            std::memory_order_release);
        g_paint_dispatch_exception_access_operation.store(
            0,
            std::memory_order_release);
        g_paint_dispatch_exception_fault_address.store(
            0,
            std::memory_order_release);
    }

    struct AutoEventWatchEntry
    {
        const char* name;
        std::atomic<std::uintptr_t> function;
        std::atomic<int> calls;
        std::atomic<int> last_array0_num;
        std::atomic<int> last_array8_num;
        std::atomic<int> total_array0_num;
        std::atomic<int> total_array8_num;
        std::atomic<int> last_i32_16;
        std::atomic<int> last_i32_24;
        std::atomic<std::int64_t> total_i32_16{0};
        std::atomic<std::int64_t> total_i32_24{0};
        // Research-only attribution of changes to RuntimePaintReplicationManager::QueuedBatches.
        // These counters are sampled immediately around the watched ProcessEvent call.  The
        // queue's total field only changes when strokes are appended, whereas its processed
        // cursor advances independently during draining.
        std::atomic<std::int64_t> last_queued_batches_total_before{-1};
        std::atomic<std::int64_t> last_queued_batches_total_after{-1};
        std::atomic<std::int64_t> last_queued_batches_total_delta{0};
        std::atomic<std::int64_t> queued_batches_total_positive_delta{0};
        std::atomic<std::int64_t> queued_batches_total_signed_delta{0};
        std::atomic<int> queued_batches_delta_observations{0};
        std::atomic<int> queued_batches_delta_unavailable{0};
        // The ProcessEvent receiver is recorded as an opaque address only.  It is
        // intentionally not dereferenced from the hook: consumers compare it with
        // the read-only component inventory captured by the pressure probe.
        std::atomic<std::uintptr_t> last_process_event_object{0};
        int last_array0_sample_len{0};
        int last_array0_sample_total_len{0};
        int last_array0_sample_element_size{1};
        std::array<std::uint8_t, AutoEventWatchSampleBytes> last_array0_sample{};
        int last_array8_sample_len{0};
        int last_array8_sample_total_len{0};
        int last_array8_sample_element_size{1};
        std::array<std::uint8_t, AutoEventWatchSampleBytes> last_array8_sample{};
    };

