    {
        float x1{0.0f};
        float y1{0.0f};
        float x2{0.0f};
        float y2{0.0f};
        float thickness{1.75f};
        EspNativeColor color{};
    };

    struct EspNativeText
    {
        float x{0.0f};
        float y{0.0f};
        EspNativeColor color{};
        wchar_t value[EspNativeMaxTextChars]{};
    };

